#include <bits/stdc++.h>

using namespace std;

string s, t;
vector<pair<char, int>> a, b;
vector<pair<int, int>> bleach;
vector<pair<char, int>> ta, tb;
bool flag = false;

void add(vector<pair<char, int>>& tren, pair<char, int> p) {
    if (!tren.empty() && tren.back().first == p.first)
        tren.back().second += p.second;
    else
        tren.push_back(p);
}

inline void addchar(vector<pair<char, int>>& tren, char c) {
    add(tren, {c, 1});
}

int popRuns(vector<pair<char, int>>& tren, int count) {
    int total = 0;
    while (count--) {
        total += tren.back().second;
        tren.pop_back();
    }
    return total;
}

void query(int acx, int acy) {
    if (flag) swap(acx, acy);

    ta.clear();
    tb.clear();

    for (int i = 0; i < acx; ++i)
        ta.push_back(a[a.size() - 1 - i]);
    for (int i = 0; i < acy; ++i)
        tb.push_back(b[b.size() - 1 - i]);

    int kolx = popRuns(a, acx);
    int koly = popRuns(b, acy);

    for (int i = acx - 1; i >= 0; --i)
        add(b, ta[i]);
    for (int i = acy - 1; i >= 0; --i)
        add(a, tb[i]);

    bleach.emplace_back(kolx, koly);
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> s >> t;

    reverse(s.begin(), s.end());
    reverse(t.begin(), t.end());

    for (char c : s) addchar(a, c);
    for (char c : t) addchar(b, c);

    while (a.size() != 1 || b.size() != 1) {
        int la = static_cast<int>(a.size());
        int lb = static_cast<int>(b.size());

        if (la < lb) {
            swap(la, lb);
            flag = true;
        }

        const char ca = a.back().first;
        const char cb = b.back().first;

        if (ca != cb) {
            if (lb <= 2) {
                if (la <= 3)
                    query(1, 1);
                else
                    query(3, 1);
            } else {
                query(1, 1);
            }
        } else {
            if (lb == 1) {
                if (la <= 3)
                    query(1, 0);
                else
                    query(3, 0);
            } else if (lb == 2) {
                if (la == 2)
                    query(1, 0);
                else
                    query(2, 1);
            } else {
                query(3, 2);
            }
        }

        flag = false;
    }

    cout << bleach.size() << '\n';
    for (const auto& [x, y] : bleach)
        cout << x << ' ' << y << '\n';

    return 0;
}

